 @page "/notepad"
 @inject IJSRuntime JS
 @implements IAsyncDisposable
 @rendermode InteractiveServer

 <PageTitle>Notepad</PageTitle>

 <h1>Notepad</h1>

 <textarea value="@Content" @oninput="OnInput" rows="15" class="form-control mb-3"></textarea>

 <div class="d-flex align-items-center gap-3 mb-3">
     <button class="btn btn-primary" @onclick="SaveNow">Save now</button>
     <button class="btn btn-danger" @onclick="Clear">Clear</button>
     @if (_lastSavedAt is not null)
     {
         <span class="text-muted">Last saved at @_lastSavedAt.Value.ToString("HH:mm:ss")</span>
     }
 </div>

 @code {
     private string Content { get; set; } = string.Empty;
     private string _savedContent = string.Empty;
     private DateTime? _lastSavedAt;
     private NotepadInterop? _interop;
     private DotNetObjectReference<Notepad>? _dotNetRef;
     private Timer? _autoSaveTimer;

     private bool HasUnsavedChanges => Content != _savedContent;

     private async Task OnInput(ChangeEventArgs e)
     {
         Content = e.Value?.ToString() ?? string.Empty;
         if (_interop is not null)
         {
             await _interop.SetHasUnsavedChangesAsync(HasUnsavedChanges);
         }
     }

     protected override async Task OnAfterRenderAsync(bool firstRender)
     {
         if (firstRender)
         {
             _interop = new NotepadInterop(JS);
             _dotNetRef = DotNetObjectReference.Create(this);
             await _interop.InitializeAsync(_dotNetRef);

             _autoSaveTimer = new Timer(AutoSaveCallback, null, TimeSpan.FromSeconds(30), TimeSpan.FromSeconds(30));
         }
     }

     [JSInvokable("OnContentLoaded")]
     public async Task OnContentLoaded(string content)
     {
         await InvokeAsync(() =>
         {
             Content = content;
             _savedContent = content;
             StateHasChanged();
         });
     }

     private async Task SaveNow()
     {
         if (_interop is not null)
         {
             await _interop.SaveAsync(Content);
             _savedContent = Content;
             _lastSavedAt = DateTime.Now;
         }
     }

     private async Task Clear()
     {
         if (_interop is not null)
         {
             Content = string.Empty;
             _savedContent = string.Empty;
             _lastSavedAt = null;
             await _interop.ClearAsync();
         }
     }

     private async void AutoSaveCallback(object? state)
     {
         if (HasUnsavedChanges && _interop is not null)
         {
             await InvokeAsync(async () =>
             {
                 await _interop.SaveAsync(Content);
                 _savedContent = Content;
                 _lastSavedAt = DateTime.Now;
                 StateHasChanged();
             });
         }
     }

     public async ValueTask DisposeAsync()
     {
         _autoSaveTimer?.Dispose();

         if (_interop is not null)
             await _interop.DisposeAsync();

         _dotNetRef?.Dispose();
     }
 }
